menu_loading_diagnostic.source:
extends "res://tests/main_menu_input_test.gd"

func _initialize() -> void:
    preload("res://scripts/parallel_runtime.gd").apply_from_environment()
    await super._initialize()

func _expect(condition: bool, message: String) -> void:
    if not condition and message.ends_with("loading should finish"):
        var transition: Node = root.get_node_or_null("MenuRunTransition")
        var report: Dictionary = {"assertion": message, "transition_valid": is_instance_valid(transition)}
        if is_instance_valid(transition):
            report["phase"] = transition.get("phase")
            report["path"] = transition.get("_path")
            var progress: Array = []
            report["loader_status"] = ResourceLoader.load_threaded_get_status(str(transition.get("_path")), progress)
            report["loader_progress"] = progress
            report["timings"] = transition.get("_performance_timings")
            var room: Node = transition.get("destination")
            report["destination_valid"] = is_instance_valid(room)
            if is_instance_valid(room):
                var fields: Dictionary = {}
                for property: Dictionary in room.get_property_list():
                    var field: String = str(property["name"])
                    if not field.begins_with("_initial_"): continue
                    var value: Variant = room.get(field)
                    if value is bool or value is int or value is float or value is String: fields[field] = value
                    elif value is Array or value is Dictionary: fields[field + "_size"] = value.size()
                report["initial_fields"] = fields
        print("RR44 MENU LOADING DIAGNOSTIC: " + JSON.stringify(report))
    super._expect(condition, message)
